namespace Pragmatic.Mapping.Mutation;

/// <summary>
///     Composable helper methods for applying DTO mutations to entities.
///     <para>
///         Provides explicit control over how each part of the mutation
///         is applied: body (scalar) properties, 1:1 navigations, and 1:N collections.
///     </para>
/// </summary>
/// <example>
///     <code>
///     // In a mutation handler:
///     var order = await repository.GetByIdAsync(id);
///
///     // Map scalar properties
///     dto.ApplyBodyTo(order);  // Generated by [GenerateBodyOnlyVariant]
///
///     // Map 1:1 navigation
///     MutationHelpers.MapOneToOne(
///         dto.ShippingAddress,
///         () => order.ShippingAddress,
///         addr => order.ShippingAddress = addr,
///         addrDto => addrDto.ToEntity(),
///         (addrDto, addr) => addrDto.ApplyToLoaded(addr));
///
///     // Map 1:N collection with sync strategy.
///     // ⚠️ Against a TRACKED entity use Pragmatic.Mapping.EFCore's EfMutationHelpers instead: it
///     // takes the CollectionEntry, which knows whether the collection was ever loaded. This form
///     // cannot know, and merging into an unloaded collection writes every element again.
///     MutationHelpers.MapOneToMany(
///         dto.Lines,
///         order.Lines,
///         d => d.Id,
///         e => e.Id,
///         lineDto => lineDto.ToEntity(),
///         (lineDto, line) => lineDto.ApplyToLoaded(line));
///     </code>
/// </example>
public static class MutationHelpers
{
    /// <summary>
    ///     Maps a 1:1 reference navigation from DTO to entity.
    ///     <para>
    ///         If the DTO value is not null, creates or updates the related entity.
    ///         If the DTO value is null, sets the navigation to null (detach).
    ///     </para>
    /// </summary>
    /// <typeparam name="TRelatedDto">The related DTO type.</typeparam>
    /// <typeparam name="TRelated">The related entity type.</typeparam>
    /// <param name="dtoValue">The DTO navigation value (may be null).</param>
    /// <param name="existingGetter">Gets the current related entity from the parent.</param>
    /// <param name="setter">Sets the related entity on the parent.</param>
    /// <param name="factory">Creates a new related entity from the DTO.</param>
    /// <param name="updater">Updates an existing related entity from the DTO.</param>
    public static void MapOneToOne<TRelatedDto, TRelated>(
        TRelatedDto? dtoValue,
        Func<TRelated?> existingGetter,
        Action<TRelated?> setter,
        Func<TRelatedDto, TRelated> factory,
        Action<TRelatedDto, TRelated>? updater = null)
        where TRelatedDto : class
        where TRelated : class
    {
        Ensure.Ensure.ThrowIfNull(existingGetter);
        Ensure.Ensure.ThrowIfNull(setter);
        Ensure.Ensure.ThrowIfNull(factory);

        if (dtoValue is null)
        {
            setter(null);
            return;
        }

        var existing = existingGetter();
        if (existing is not null && updater is not null)
        {
            // Update existing entity in-place
            updater(dtoValue, existing);
        }
        else
        {
            // Create new entity from DTO
            setter(factory(dtoValue));
        }
    }

    /// <summary>
    ///     Maps a 1:N collection navigation from DTO to entity.
    ///     <para>
    ///         Uses the specified <paramref name="strategy" /> to determine
    ///         how to synchronize items between DTO and entity collections.
    ///     </para>
    ///     <para>
    ///         ⚠️ <b><paramref name="entityCollection" /> must already be loaded.</b> A keyed merge
    ///         decides what to keep by looking at what is there, and an EF collection that was never
    ///         included is indistinguishable from an empty one: every item the DTO carries then looks
    ///         new. Measured against PostgreSQL — a write that sent the same two rows back wrote four,
    ///         with no error and a successful <c>SaveChanges</c>. The type system cannot express this,
    ///         so it is said here.
    ///     </para>
    ///     <para>
    ///         Callers that go through a mutation get it for free: the generated invoker loads the
    ///         navigations its children write, and the ones those children write in turn. A caller
    ///         invoking <c>ApplyTo</c> by hand owns the requirement, and where EF is present the
    ///         generated <c>ApplyTo(entity, DbContext)</c> asks EF and refuses rather than duplicating.
    ///     </para>
    ///     <para>
    ///         ⚠️ <b>Changing the strategy does not help.</b> <c>AddOnly</c> removes nothing, but it
    ///         still reads the collection to decide what is new — so against an unloaded one every
    ///         element looks new and the rows are written twice, exactly as under <c>Sync</c>. Measured:
    ///         the two behave identically here. The only remedy is to load the collection; the choice of
    ///         strategy protects against losing rows, not against writing them twice.
    ///     </para>
    /// </summary>
    /// <typeparam name="TRelatedDto">The related DTO type.</typeparam>
    /// <typeparam name="TRelated">The related entity type.</typeparam>
    /// <typeparam name="TKey">The key type used to match items.</typeparam>
    /// <param name="dtoItems">The DTO collection (may be null or empty).</param>
    /// <param name="entityCollection">The entity's mutable collection, already loaded.</param>
    /// <param name="dtoKeySelector">Extracts the matching key from a DTO item.</param>
    /// <param name="entityKeySelector">Extracts the matching key from an entity item.</param>
    /// <param name="factory">Creates a new entity from a DTO item.</param>
    /// <param name="updater">Updates an existing entity from a DTO item.</param>
    /// <param name="strategy">The collection synchronization strategy (default: Sync).</param>
    public static void MapOneToMany<TRelatedDto, TRelated, TKey>(
        IEnumerable<TRelatedDto>? dtoItems,
        ICollection<TRelated> entityCollection,
        Func<TRelatedDto, TKey> dtoKeySelector,
        Func<TRelated, TKey> entityKeySelector,
        Func<TRelatedDto, TRelated> factory,
        Action<TRelatedDto, TRelated>? updater = null,
        CollectionStrategy strategy = CollectionStrategy.Sync)
        where TRelatedDto : class
        where TRelated : class
        where TKey : notnull
    {
        // Checked before the guards: Ignore means the caller is not writing this collection, so
        // demanding the selectors and the factory it will never use would be theatre.
        if (strategy == CollectionStrategy.Ignore)
            return;

        Ensure.Ensure.ThrowIfNull(entityCollection);
        Ensure.Ensure.ThrowIfNull(dtoKeySelector);
        Ensure.Ensure.ThrowIfNull(entityKeySelector);
        Ensure.Ensure.ThrowIfNull(factory);

        var sourceItems = dtoItems?.ToList() ?? [];

        switch (strategy)
        {
            case CollectionStrategy.Sync:
                SyncCollection(sourceItems, entityCollection, dtoKeySelector, entityKeySelector, factory, updater);
                break;

            case CollectionStrategy.AddOnly:
                AddNewItems(sourceItems, entityCollection, dtoKeySelector, entityKeySelector, factory, updater);
                break;

            case CollectionStrategy.Replace:
                ReplaceCollection(sourceItems, entityCollection, factory);
                break;

            default:
                throw new ArgumentOutOfRangeException(nameof(strategy), strategy, "Unknown collection strategy.");
        }
    }

    /// <summary>
    ///     Full sync: add new, update existing, remove missing.
    /// </summary>
    private static void SyncCollection<TRelatedDto, TRelated, TKey>(
        List<TRelatedDto> dtoItems,
        ICollection<TRelated> entityCollection,
        Func<TRelatedDto, TKey> dtoKeySelector,
        Func<TRelated, TKey> entityKeySelector,
        Func<TRelatedDto, TRelated> factory,
        Action<TRelatedDto, TRelated>? updater)
        where TRelatedDto : class
        where TRelated : class
        where TKey : notnull
    {
        // Build entity lookup and collect removals in a single pass over entityCollection.
        // Reject duplicate keys up front: a keyed sync is ambiguous when a key maps to more than
        // one item on either side (see DuplicateMappingKeyException).
        var entityLookup = new Dictionary<TKey, TRelated>(entityCollection.Count);
        var toRemove = new List<TRelated>(entityCollection.Count);
        var dtoKeys = new HashSet<TKey>(dtoItems.Count);

        foreach (var dtoItem in dtoItems)
        {
            var key = dtoKeySelector(dtoItem);

            // An element without an assigned key is new, not "the default element": it addresses
            // nothing, so two of them are not ambiguous. Counting them as duplicates would make it
            // impossible to create an aggregate with more than one child, or to add two in an
            // update — with a 500, not a domain error.
            if (IsUnassigned(key))
                continue;

            if (!dtoKeys.Add(key))
                throw new DuplicateMappingKeyException("DTO", key);
        }

        foreach (var entity in entityCollection)
        {
            var key = entityKeySelector(entity);
            if (!entityLookup.TryAdd(key, entity))
                throw new DuplicateMappingKeyException("entity", key);
            if (!dtoKeys.Contains(key))
                toRemove.Add(entity);
        }

        // Remove items that are not in the DTO collection
        foreach (var item in toRemove)
            entityCollection.Remove(item);

        // Add new or update existing
        foreach (var dtoItem in dtoItems)
        {
            var key = dtoKeySelector(dtoItem);

            // An unassigned key neither consults the lookup nor enters it. Without this the second
            // new element would find the one created by the first — same default key — and update it
            // instead of creating another: a child lost silently, which is worse than an exception.
            if (IsUnassigned(key))
            {
                entityCollection.Add(factory(dtoItem));
                continue;
            }

            if (entityLookup.TryGetValue(key, out var existing))
            {
                // Update existing
                updater?.Invoke(dtoItem, existing);
            }
            else
            {
                // Add new and track it in the lookup. DTO keys are already guaranteed unique
                // above, so this is defensive: it keeps the lookup consistent with the collection.
                var created = factory(dtoItem);
                entityCollection.Add(created);
                entityLookup[key] = created;
            }
        }
    }

    /// <summary>
    ///     Add-only: new items are added, existing items are updated, nothing is removed.
    /// </summary>
    private static void AddNewItems<TRelatedDto, TRelated, TKey>(
        List<TRelatedDto> dtoItems,
        ICollection<TRelated> entityCollection,
        Func<TRelatedDto, TKey> dtoKeySelector,
        Func<TRelated, TKey> entityKeySelector,
        Func<TRelatedDto, TRelated> factory,
        Action<TRelatedDto, TRelated>? updater)
        where TRelatedDto : class
        where TRelated : class
        where TKey : notnull
    {
        // Reject duplicate DTO keys up front: they would otherwise create duplicate child entities.
        // Unassigned keys are excluded for the reason given in SyncCollection: they are new elements,
        // not repetitions of the same one.
        var dtoKeys = new HashSet<TKey>(dtoItems.Count);
        foreach (var dtoItem in dtoItems)
        {
            var key = dtoKeySelector(dtoItem);
            if (IsUnassigned(key))
                continue;

            if (!dtoKeys.Add(key))
                throw new DuplicateMappingKeyException("DTO", key);
        }

        // Build the lookup with an explicit indexer instead of ToDictionary so a duplicate entity
        // key throws a clear domain exception instead of a raw ArgumentException.
        var entityLookup = new Dictionary<TKey, TRelated>(entityCollection.Count);
        foreach (var entity in entityCollection)
        {
            var key = entityKeySelector(entity);
            if (!entityLookup.TryAdd(key, entity))
                throw new DuplicateMappingKeyException("entity", key);
        }

        foreach (var dtoItem in dtoItems)
        {
            var key = dtoKeySelector(dtoItem);
            if (!IsUnassigned(key) && entityLookup.TryGetValue(key, out var existing))
            {
                // Update existing
                updater?.Invoke(dtoItem, existing);
            }
            else
            {
                // Add new
                entityCollection.Add(factory(dtoItem));
            }
        }
    }

    /// <summary>
    ///     Whether the key is the default one: the element has no identity yet.
    /// </summary>
    /// <remarks>
    ///     ⚠️ <c>0</c>, <c>Guid.Empty</c> and <c>null</c> mean "new", not "the element
    ///     number zero". A persisted entity never has a default key — <c>PersistenceId</c> is
    ///     <c>ValueGeneratedNever</c> and assigned in the constructor — so the distinction takes no
    ///     match away from anyone.
    /// </remarks>
    private static bool IsUnassigned<TKey>(TKey key)
        => EqualityComparer<TKey>.Default.Equals(key, default!);

    /// <summary>
    ///     Replace: clear all and recreate from DTO collection.
    /// </summary>
    private static void ReplaceCollection<TRelatedDto, TRelated>(
        List<TRelatedDto> dtoItems,
        ICollection<TRelated> entityCollection,
        Func<TRelatedDto, TRelated> factory)
        where TRelatedDto : class
        where TRelated : class
    {
        entityCollection.Clear();
        foreach (var item in dtoItems)
            entityCollection.Add(factory(item));
    }
}
